addedCss:
.trend-selected {margin:0 20px 16px;padding:14px;border:1px solid var(--mcn-line);border-radius:8px;background:var(--secondary);min-width:0;}
.trend-selected-controls {display:flex;flex-wrap:wrap;align-items:center;gap:10px 20px;}
.trend-selected-controls label {display:flex;flex-wrap:wrap;align-items:center;gap:8px;font-size:14px;min-width:0;max-width:100%;}
.trend-selected-controls select {min-height:44px;max-width:100%;margin-left:0;font-size:14px;}
.trend-selected-reading {display:flex;flex-wrap:wrap;gap:12px 32px;padding-top:12px;}
.trend-selected-reading>p {flex-basis:100%;margin:0;}
.trend-selected-reading>div {min-width:0;max-width:100%;flex:1 1 220px;}
.trend-selected-reading span,.trend-selected-reading small {display:block;font-size:13px;line-height:1.6;color:var(--mcn-muted);overflow-wrap:anywhere;}
.trend-selected-reading strong {display:block;font-size:clamp(22px,2vw,30px);line-height:1.35;font-weight:650;font-variant-numeric:tabular-nums;overflow-wrap:anywhere;margin:4px 0;}
.trend-point-chart {min-width:0;}
.trend-point-chart:focus-visible {outline:2px solid var(--ring);outline-offset:-3px;}
@media(max-width:760px) {.trend-selected {margin-inline:16px;}.trend-selected-controls label,.trend-selected-controls select {width:100%;}.trend-selected-reading {gap:12px;}}
